from fai.consts import START_CODON_OFFSET
from fai.contracts import Read
from fai.logic import calculate_deltas_by_subset


def test_calculate_deltas_by_subset():
    gene_dict = {
        "gene1": "",  # noqa: E501
        "gene2": "",  # noqa: E501
        "gene3": "",  # noqa: E501
    }

    reads_spacing = 3
    base_delta = 12
    min_size = 25
    max_size = 35

    reads = [
        Read(
            gene,
            START_CODON_OFFSET
            - (base_delta + (size - min_size) - 1)
            + offset * reads_spacing,
            size,
        )
        for size in range(min_size, max_size)
        for gene in gene_dict
        for offset in range(
            0,
            (len(gene_dict[gene]) - START_CODON_OFFSET - base_delta - min_size - 1)
            // reads_spacing
            + 1,
        )
    ]

    deltas_by_subset = calculate_deltas_by_subset(reads, gene_dict)

    assert deltas_by_subset == {
        f"{size}:F{flanker}:{nt}": base_delta + (size - min_size)
        for size in range(min_size, max_size)
        for flanker in range(8)
        for nt in ["A", "T", "C", "G"]
    }
